<style>
@font-face{font-family:Manrope;src:url(/app-links/manrope-400.woff2) format("woff2");font-style:normal;font-weight:400;font-display:swap}@font-face{font-family:Manrope;src:url(/app-links/manrope-600.woff2) format("woff2");font-style:normal;font-weight:600 800;font-display:swap}
:root{color-scheme:light dark;--bg:#f6f4f1;--surface:#fff;--ink:#282725;--muted:#696661;--line:#e6e1db;--accent:#a94b35}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Manrope,ui-sans-serif,system-ui,sans-serif;min-height:100svh;display:grid;place-items:center;padding:24px 16px}main{width:min(100%,420px);padding:32px;background:var(--surface);border:1px solid var(--line);border-radius:22px;box-shadow:0 12px 40px #28272508}.brand{font-size:25px;font-weight:800;letter-spacing:-1.5px}.app-icon{margin:32px 0 20px;width:48px;height:48px;border:1px solid var(--line);border-radius:14px;display:grid;place-items:center;color:var(--accent);font-size:28px}h1{font-size:26px;line-height:1.22;letter-spacing:-.7px;margin:0 0 12px;overflow-wrap:anywhere}p{font-size:15px;color:var(--muted);line-height:1.65;margin:0 0 26px}form{margin:10px 0}button,a.primary,a.secondary{font:inherit;font-weight:650;font-size:14px;min-height:48px;padding:12px 18px;width:100%;border:1px solid var(--line);border-radius:11px;text-align:center;text-decoration:none;display:flex;gap:12px;justify-content:center;align-items:center;cursor:pointer;transition:background 160ms,transform 160ms}button.primary,a.primary{background:var(--accent);border-color:var(--accent);color:#fff}.secondary{margin-top:10px;background:var(--surface);color:var(--ink)}aside{font-size:12px;line-height:1.7;color:var(--muted);border-top:1px solid var(--line);padding-top:20px;margin-top:24px}a:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:4px}button:disabled{opacity:.6;cursor:wait}[hidden]{display:none!important}@media(hover:hover){button:hover,a.primary:hover{transform:translateY(-1px)}}@media(prefers-color-scheme:dark){:root{--bg:#181817;--surface:#222220;--ink:#f2efea;--muted:#b6b0a7;--line:#403c36;--accent:#bd6047}}@media(max-width:360px){main{padding:24px}h1{font-size:24px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;transform:none!important}}
</style>
